Here is the commit message:
iommu/riscv: Remove overflows on the invalidation path

Since RISC-V supports a sign extended page table it should support
a gather->end of ULONG_MAX, but if this happens it will infinite loop
because of the overflow.

Also avoid overflow computing the length by moving the +1 to the other
side of the <

Fixes: 488ffbf18171 ("iommu/riscv: Paging domain support")
Signed-off-by: Jason Gunthorpe <jgg@nvidia.com>
Signed-off-by: Joerg Roedel <joerg.roedel@amd.com>

Here is the root cause:
The invalidation path allows gather->end of ULONG_MAX for the sign-extended page table. The old code computed `len = end - start + 1`, which overflows when `end` is ULONG_MAX (becoming 0), causing the condition to incorrectly skip per-page invalidation. Additionally, the `for` loop `iova += PAGE_SIZE` overflows when `iova` wraps around, resulting in an infinite loop because the wrap makes `iova < end` always true when `end` is ULONG_MAX.

Here is the patch:

 static void riscv_iommu_iotlb_inval(struct riscv_iommu_domain *domain,
 				    unsigned long start, unsigned long end)
 {
 	struct riscv_iommu_bond *bond;
 	struct riscv_iommu_device *iommu, *prev;
 	struct riscv_iommu_command cmd;
-	unsigned long len = end - start + 1;
-	unsigned long iova;

 	/*
 	 * For each IOMMU linked with this protection domain (via bonds->dev),
 	 * an IOTLB invaliation command will be submitted and executed.
 	 *
 	 * Possbile race with domain attach flow is handled by sequencing
 	 * bond creation - riscv_iommu_bond_link(), and device directory
 	 * update - riscv_iommu_iodir_update().
 	 *
 	 * PTE Update / IOTLB Inval           Device attach & directory update
 	 * --------------------------         --------------------------
 	 * update page table entries          add dev to the bond list
 	 * FENCE RW,RW                        FENCE RW,RW
 	 * For all IOMMUs: (can be empty)     Update FSC/PSCID
 	 *   FENCE IOW,IOW                      FENCE IOW,IOW
 	 *   IOTLB.INVAL                        IODIR.INVAL
 	 *   IOFENCE.C
 	 *
 	 * If bond list is not updated with new device, directory context will
 	 * be configured with already valid page table content. If an IOMMU is
 	 * linked to the protection domain it will receive invalidation
 	 * requests for updated page table entries.
 	 */
 	smp_mb();

 	rcu_read_lock();

 	prev = NULL;
 	list_for_each_entry_rcu(bond, &domain->bonds, list) {
 		iommu = dev_to_iommu(bond->dev);

 		/*
 		 * IOTLB invalidation request can be safely omitted if already sent
 		 * to the IOMMU for the same PSCID, and with domain->bonds list
 		 * arranged based on the device's IOMMU, it's sufficient to check
 		 * last device the invalidation was sent to.
 		 */
 		if (iommu == prev)
 			continue;

 		riscv_iommu_cmd_inval_vma(&cmd);
 		riscv_iommu_cmd_inval_set_pscid(&cmd, domain->pscid);
-		if (len && len < RISCV_IOMMU_IOTLB_INVAL_LIMIT) {
-			for (iova = start; iova < end; iova += PAGE_SIZE) {
+		if (end - start < RISCV_IOMMU_IOTLB_INVAL_LIMIT - 1) {
+			unsigned long iova = start;
+
+			do {
 				riscv_iommu_cmd_inval_set_addr(&cmd, iova);
 				riscv_iommu_cmd_send(iommu, &cmd);
-			}
+			} while (!check_add_overflow(iova, PAGE_SIZE, &iova) &&
+				 iova < end);
 		} else {
 			riscv_iommu_cmd_send(iommu, &cmd);
 		}
 		prev = iommu;
 	}

 	prev = NULL;
 	list_for_each_entry_rcu(bond, &domain->bonds, list) {
 		iommu = dev_to_iommu(bond->dev);
 		if (iommu == prev)
 			continue;

 		riscv_iommu_cmd_sync(iommu, RISCV_IOMMU_IOTINVAL_TIMEOUT);
 		prev = iommu;
 	}
 	rcu_read_unlock();
 }



